export const ICON_NAMES = Object.keys(PLANNER_ICONS);
export const isIcon = (picture: string) => picture.startsWith('ph:');
export const iconKey = (picture: string) => picture.slice(3);

/** Pictures the first planner used, and the icon each one becomes */
export const LEGACY_TO_ICON: Record<string, string> = {
  sun: 'Sun', toothbrush: 'Tooth', soap: 'HandSoap', shirt: 'TShirt', quilt: 'Bed', bowl: 'BowlFood',
  backpack: 'Backpack', shoes: 'Sneaker', bus: 'Student', book: 'BookOpen', pencil: 'PencilSimple',
  guitar: 'MusicNotes', paintbrush: 'PaintBrush', friends: 'UsersThree', puzzle: 'PuzzlePiece',
  apple: 'OrangeSlice', sandwich: 'Hamburger', cookie: 'Cookie', dish: 'ForkKnife', cup: 'Drop',
  milk: 'Coffee', tree: 'Tree', swing: 'Park', 'teddy-bear': 'Shapes', ball: 'SoccerBall', bike: 'Bicycle',
  swimsuit: 'SwimmingPool', dog: 'Dog', tv: 'Television', box: 'Broom', moon: 'MoonStars',
  bathtub: 'Bathtub', pyjamas: 'Hoodie', bed: 'Bed', star: 'Star', face: 'HandSoap',
};

const INK = '#2D2200';

/** One icon, centred on (cx, cy), `size` points across */
export const PlannerIcon: React.FC<{ name: string; cx: number; cy: number; size: number; color?: string }> = ({ name, cx, cy, size, color = INK }) => {
  const icon = PLANNER_ICONS[name] ?? PLANNER_ICONS.Star;
  const d = size < 34 ? icon.b : size < 96 ? icon.r : icon.t;
  const k = size / 256;
  return (
    <g transform={`translate(${cx - size / 2} ${cy - size / 2}) scale(${k})`}>
      <path d={d} fill={color} />
    </g>
  );
};

/** A planner item's graphic: an icon, or (for anything picked from the library) a picture */
export const PlannerGraphic: React.FC<{ picture: string; cx: number; cy: number; size: number }> = ({ picture, cx, cy, size }) =>
  isIcon(picture) ? (
    // Icons fill their box more than template-framed pictures do, so they sit a touch smaller
    <PlannerIcon name={iconKey(picture)} cx={cx} cy={cy} size={size * 0.86} />
  ) : (
    <Picture name={picture} cx={cx} cy={cy} size={size} />
  );

/** A graphic in its own small SVG, for cards, pickers and drag previews */
export const GraphicThumb: React.FC<{ picture: string; size?: number }> = ({ picture, size = 40 }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" aria-hidden="true" className="shrink-0">
    {isIcon(picture) ? <PlannerIcon name={iconKey(picture)} cx={50} cy={50} size={size < 34 ? 92 : 80} /> : <Picture name={picture} cx={50} cy={50} size={100} />}
  </svg>
);

/**
 * The icon that best fits what someone typed ("Pack socks" -> Sock), or null. Words count
 * with or without a plural "s"; the last word that matches wins, since it's usually the thing.
 */
export function iconForWords(text: string): string | null {
  const tokens = text.toLowerCase().match(/[a-z]+/g) ?? [];
  const forms = (w: string) => [w, w.replace(/(es|s)$/, ''), w + 's'];
  for (let i = tokens.length - 1; i >= 0; i--) {
    const want = forms(tokens[i]);
    const hit = ICON_NAMES.find((n) => {
      const words = PLANNER_ICONS[n].words.split(' ').concat(n.toLowerCase());
      return words.some((w) => want.includes(w) || forms(w).includes(tokens[i]));
    });
    if (hit && tokens[i].length > 2) return `ph:${hit}`;
  }
  return null;
}
